fn balance_delays(netlist: &Netlist, compiled: &mut reda::compile::CompiledCircuit) {
    use reda::compile::{geometry, topology::GateKind};
    use reda::redstone::{simulator::position::Position, world::block::BlockKind};
    let Ok(report) = reda::compile::routing_stats::analyze(netlist, compiled) else { return; };
    let costs: HashMap<_, _> = report.edges.iter().map(|edge|
        (edge.sink.clone(), (edge.total().repeaters * 2) as u64)).collect();
    let mut arrival: HashMap<String, u64> = netlist.inputs.iter().map(|n| (n.clone(), 0)).collect();
    let mut pending: Vec<_> = netlist.gates.iter().enumerate().collect();
    let mut edits = 0;
    while !pending.is_empty() {
        let before = pending.len();
        pending.retain(|&(index, gate)| {
            if !gate.inputs.iter().all(|n| arrival.contains_key(n)) { return true; }
            let mut times: Vec<_> = gate.inputs.iter().enumerate().map(|(i,n)|
                arrival[n] + costs[&format!("{}.in[{}]",gate.output,i)]).collect();
            let latest = times.iter().copied().max().unwrap_or(0);
            if matches!(gate.kind, GateKind::Nor(_)) {
                let facing = compiled.gate_facings[index];
                let (x,y,z) = compiled.gate_output_positions[&gate.output];
                let support = Position::new(x,y,z).offset(geometry::output_direction(facing).opposite());
                for (i, direction) in geometry::input_directions(facing).into_iter().take(gate.inputs.len()).enumerate() {
                    let socket = support.offset(direction);
                    let mut state = compiled.world.get(socket.x,socket.y,socket.z).clone();
                    if state.kind != BlockKind::Repeater { continue; }
                    let extra = ((latest-times[i])/2).min(4-state.delay as u64);
                    if extra > 0 {
                        eprintln!("balanced {} input {} by {} redstone ticks", gate.output, i, extra);
                        state.delay += extra as u8;
                        compiled.world.set(socket.x,socket.y,socket.z,state);
                        times[i] += extra*2;
                        edits += 1;
                    }
                }
            }
            arrival.insert(gate.output.clone(), times.into_iter().max().unwrap_or(0) +
                if matches!(gate.kind, GateKind::Nor(_)) { 2 } else { 0 });
            false
        });
        assert!(pending.len() < before, "cyclic delay model");
    }
    eprintln!("delay-balanced sockets: {edits}");
}
